"use client"

import CascadeSignupForm from "@/components/ui/cascade-signup-form"

// Unsplash photos, inlined so the demo fetches nothing: night sky over mountains
// (unsplash.com/photos/1519681393784-d120267933ba) and four portraits.
const NIGHT = "data:image/webp;base64,"
const FACES = [
  "data:image/webp;base64,", // 1494790108377-be9c29b29330
  "data:image/webp;base64,", // 1507003211169-0a1dd7228f2d
  "data:image/webp;base64,", // 1438761681033-6461ffad8d80
  "data:image/webp;base64,", // 1500648767791-00dcc994a43e
]

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms))

export default function Demo() {
  return (
    <div className="flex min-h-[820px] w-full items-center justify-center bg-background px-4 py-12">
      <CascadeSignupForm
        image={NIGHT}
        imageAlt="Snow-capped mountains under a starry night sky"
        avatars={FACES}
        // Try taken@example.com to see the server-side check.
        checkEmail={async (email) => {
          await wait(700)
          return email.toLowerCase() === "taken@example.com" ? "That email already has an account" : ""
        }}
        onSubmit={() => wait(1400)}
      />
    </div>
  )
}
